import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"One Language, Multiple Interpreters — A Graded Arrow Calculus","description":"","frontmatter":{"title":"One Language, Multiple Interpreters — A Graded Arrow Calculus","type":"adr","date":"2026-09-08T00:00:00.000Z","status":"proposed","status_note":"Proposed — one graded arrow language; interpreters implement `Model`."},"headers":[],"relativePath":"handl/project/adrs/0098-one-language-multiple-interpreters.md","filePath":"vendored/handl/project/adrs/0098-one-language-multiple-interpreters.md"}'),a={name:`handl/project/adrs/0098-one-language-multiple-interpreters.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0098-one-language-multiple-interpreters-—-a-graded-arrow-calculus" tabindex="-1">ADR-0098: One Language, Multiple Interpreters — A Graded Arrow Calculus <a class="header-anchor" href="#adr-0098-one-language-multiple-interpreters-—-a-graded-arrow-calculus" aria-label="Permalink to “ADR-0098: One Language, Multiple Interpreters — A Graded Arrow Calculus”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><strong>Everything is an arrow, and the arrow language is graded.</strong> Grades are the single mechanism for effects, dimensions and refinement.</li><li><strong>The graded-theory map is the grade vocabulary</strong> — each grade names its theory; no ad-hoc annotations.</li><li><strong><code>plugin-engine</code> is the base <code>Term</code> language plus the <code>Model</code> trait</strong> that every interpreter implements.</li><li><strong>All primitives and combinators are optional per runtime</strong>; a model declares what it supports, so no interpreter carries dead surface.</li><li><strong>The arrow-handler algebra is data-driven</strong> and interprets <code>Term</code>; handlers are composed, not baked into the engine.</li><li><strong><code>Scheme</code>/<code>Term</code> is the calculus</strong>, with a fixed shape; interpreters consume it, they do not extend it.</li><li><strong>Surface arrow combinators are <code>Term</code> sugar</strong>; bounded repetition is a combinator, not a primitive.</li><li><strong>Sorts are grade records</strong>; the <code>data</code> keyword is removed and inductive sorts are ordinary <code>sort</code> values.</li><li><strong>Generics are <code>Generic</code> tagged applications over grades</strong>, not a separate type-class layer.</li><li><strong>Effects stay structural and handlers composable</strong>: an <code>op</code> declares its sorts and grade in <code>Language</code> data; a model supplies the handlers.</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>One language with several interpreters forces the semantics out of the interpreter: if a construct means anything, it must be in <code>Term</code> + grades + handlers, not in a Rust arm of one engine. The previous split produced a language per engine and made equivalences unprovable.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>A language per interpreter</strong> — the semantics would diverge.</li><li><strong>Special-case <code>data</code>/generics</strong> — both are <code>sort</code>/<code>Generic</code> over grades.</li><li><strong>Type classes or interfaces</strong> — grades and <code>Generic</code> cover the same ground.</li><li><strong>Ungraded primitives</strong> — every effect carries a grade or the calculus is impure.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>Engines shrink to <code>Model</code> implementations; surface sugar lowers to <code>Term</code>.</li><li>Grades pervade the language — a cost paid once, not per construct.</li><li>Bounded repetition and combinators are library surface, not kernel.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>engine/</code> — <code>Term</code>, the <code>Model</code> trait, the arrow-handler algebra.</li><li><code>crates/handl-kit-data-canonical/data/</code> — grades, sorts, eval schemes.</li><li>Engine parity tests (<code>engine-test</code>) across interpreters.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>+The graded-theory map, <code>Term</code> shape, syntax details, handler algebra and the +frontier questions: +<a href="./../design/0098-one-language-multiple-interpreters.html"><code>design/0098-one-language-multiple-interpreters.md</code></a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};